import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int A = sc.nextInt();
        int L = sc.nextInt();
        int N = sc.nextInt();

        int photoArea = A * L;
        int bestId = -1;
        long bestArea = Long.MAX_VALUE;

        for (int i = 1; i <= N; i++) {
            int X = sc.nextInt();
            int Y = sc.nextInt();

            boolean fits = (X >= A && Y >= L) || (X >= L && Y >= A);

            if (fits) {
                long frameArea = (long) X * Y;
                long wasted = frameArea - photoArea;
                if (wasted < bestArea) {
                    bestArea = wasted;
                    bestId = i;
                }
            }
        }

        System.out.println(bestId);
    }
}
